+pub(super) fn narrow_noted(
+    mut path: crate::cl::Toolpath,
+    params: &OpParams,
+    region: &crate::geo2d::Region,
+    tool_diameter: f64,
+    cleared_around: bool,
+    unit: crate::units::Unit,
+) -> crate::cl::Toolpath {
