+        OpParams::Pocket { stock_to_leave, .. }
+        | OpParams::Adaptive2D { stock_to_leave, .. }
+        | OpParams::Offset2D { stock_to_leave, .. } => *stock_to_leave,
+        _ => return path,
+    };
